'use client';

import { useRef, useEffect, useState, useCallback } from 'react';
import dynamic from 'next/dynamic';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';

// ─── Loading Skeleton ────────────────────────────────────────────────────────

function LoadingSkeleton() {
  return (
    <div className="w-full h-full flex items-center justify-center" aria-label="Loading 3D scene">
      <div className="relative w-32 h-32">
        <span className="absolute inset-0 rounded-full border border-primary/20 animate-ping" style={{ animationDuration: '1.6s' }} />
        <span className="absolute inset-4 rounded-full border border-primary/30 animate-ping" style={{ animationDuration: '1.6s', animationDelay: '200ms' }} />
        <span className="absolute inset-8 rounded-full border border-primary/40 animate-ping" style={{ animationDuration: '1.6s', animationDelay: '400ms' }} />
        <span className="absolute inset-[54px] rounded-full bg-primary/40 animate-pulse" />
      </div>
    </div>
  );
}

// ─── Lazy Spline Import (SSR disabled, module-level fallback) ────────────────

const Spline = dynamic(() => import('@splinetool/react-spline'), {
  ssr: false,
  loading: () => <LoadingSkeleton />,
});

// ─── Types ───────────────────────────────────────────────────────────────────

interface DroneSceneProps {
  /** Spline .splinecode scene URL */
  sceneUrl?: string;
  /** Name of the drone object inside the Spline scene */
  droneName?: string;
  /** Extra Tailwind classes on the root wrapper */
  className?: string;
  /**
   * Override cursor-tracking toggle.
   * Defaults to `true` on desktop, `false` on mobile.
   */
  enableParallax?: boolean;
}

// ─── Spring config ───────────────────────────────────────────────────────────

const SPRING = { stiffness: 50, damping: 18, mass: 1.2 } as const;

// ─── Component ───────────────────────────────────────────────────────────────

export default function DroneScene({
  sceneUrl = 'https://prod.spline.design/w1MzRxYCg9LT1Zi6/scene.splinecode',
  droneName = 'Drone',
  className = '',
  enableParallax,
}: DroneSceneProps) {
  const splineRef  = useRef<any>(null);
  const rafRef     = useRef<number>(0);
  const targetPos  = useRef({ x: 0, y: 0 });
  const smoothPos  = useRef({ x: 0, y: 0 });

  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  // Resolved: whether cursor tracking is active
  const trackCursor = enableParallax ?? !isMobile;

  // ── Motion values for CSS perspective tilt ─────────────────────────────────
  const rawX    = useMotionValue(0);
  const rawY    = useMotionValue(0);
  const springX = useSpring(rawX, SPRING);
  const springY = useSpring(rawY, SPRING);
  // Map normalised [-1, 1] → rotation degrees
  const rotateY = useTransform(springX, [-1, 1], [-10, 10]);
  const rotateX = useTransform(springY, [-1, 1], [6, -6]);

  // ── Mobile detection ───────────────────────────────────────────────────────
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener('resize', check, { passive: true });
    return () => window.removeEventListener('resize', check);
  }, []);

  // ── Global mouse-move → normalised target position ────────────────────────
  const onMouseMove = useCallback((e: MouseEvent) => {
    targetPos.current = {
      x: (e.clientX / window.innerWidth)  * 2 - 1,
      y: (e.clientY / window.innerHeight) * 2 - 1,
    };
  }, []);

  useEffect(() => {
    if (!trackCursor) return;
    window.addEventListener('mousemove', onMouseMove, { passive: true });
    return () => window.removeEventListener('mousemove', onMouseMove);
  }, [trackCursor, onMouseMove]);

  // ── RAF loop: lerp smooth position, drive CSS tilt + Spline parallax ──────
  useEffect(() => {
    if (!trackCursor) return;

    const tick = () => {
      const lerp = 0.07;
      smoothPos.current.x += (targetPos.current.x - smoothPos.current.x) * lerp;
      smoothPos.current.y += (targetPos.current.y - smoothPos.current.y) * lerp;

      // Feed into framer-motion springs → CSS perspective tilt
      rawX.set(smoothPos.current.x);
      rawY.set(smoothPos.current.y);

      // Also nudge the Spline object for a subtle parallax depth effect.
      // The object name must match whatever is in your Spline scene.
      if (splineRef.current) {
        const obj = splineRef.current.findObjectByName(droneName);
        if (obj) {
          obj.position.x = smoothPos.current.x * 25;
          obj.position.y = -smoothPos.current.y * 18;
        }
      }

      rafRef.current = requestAnimationFrame(tick);
    };

    rafRef.current = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(rafRef.current);
      rawX.set(0);
      rawY.set(0);
    };
  }, [trackCursor, droneName, rawX, rawY]);

  // ── Spline onLoad ──────────────────────────────────────────────────────────
  function onLoad(app: any) {
    splineRef.current = app;
    setIsLoaded(true);
  }

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    /**
     * Outer div handles the idle floating animation via CSS.
     * Keeping it on a separate element prevents transform conflicts
     * with the framer-motion tilt on the inner motion.div.
     */
    <div className={`relative w-full h-full select-none animate-drone-float ${className}`}>

      {/* Perspective tilt wrapper — desktop only */}
      <motion.div
        className="w-full h-full"
        style={{
          perspective: '1200px',
          rotateX: isMobile ? 0 : rotateX,
          rotateY: isMobile ? 0 : rotateY,
          transformStyle: 'preserve-3d',
        }}
        initial={{ opacity: 0, scale: 0.96 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 1, ease: [0.25, 0.4, 0.25, 1] }}
      >
        {/* Skeleton overlay — visible until Spline scene is fully loaded */}
        {!isLoaded && (
          <div className="absolute inset-0 z-10 pointer-events-none">
            <LoadingSkeleton />
          </div>
        )}

        {/* Spline canvas — pointer-events-none keeps scroll/clicks passthrough */}
        <motion.div
          className="w-full h-full pointer-events-none"
          animate={{ opacity: isLoaded ? 1 : 0 }}
          transition={{ duration: 0.8, ease: 'easeOut' }}
        >
          <Spline
            scene={sceneUrl}
            onLoad={onLoad}
            style={{ width: '100%', height: '100%' }}
          />
        </motion.div>
      </motion.div>

      {/* Ambient glow shadow — reinforces the floating feel */}
      {isLoaded && (
        <div
          aria-hidden
          className="absolute bottom-4 left-1/2 -translate-x-1/2 w-2/3 h-6 rounded-full bg-primary/10 blur-2xl pointer-events-none"
        />
      )}
    </div>
  );
}
